from solution import move_one_ball
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


def reference(arr):
    """Obviously-correct reference: sorted rotation <=> at most one wrap drop."""
    if len(arr) == 0:
        return True
    n = len(arr)
    drops = sum(1 for i in range(n) if arr[i] > arr[(i + 1) % n])
    return drops <= 1


def right_shift(arr, k):
    n = len(arr)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return list(arr)
    return arr[-k:] + arr[:-k]


# ---- concrete examples from spec ----

def test_spec_example_true():
    assert move_one_ball([3, 4, 5, 1, 2]) is True


def test_spec_example_false():
    assert move_one_ball([3, 5, 4, 1, 2]) is False


def test_empty_returns_true():
    assert move_one_ball([]) is True


def test_single_element_returns_true():
    assert move_one_ball([7]) is True
    assert move_one_ball([-100]) is True


def test_already_sorted_returns_true():
    assert move_one_ball([1, 2, 3, 4, 5]) is True
    assert move_one_ball([-5, -1, 0, 10]) is True


def test_two_elements_sorted_true():
    assert move_one_ball([1, 2]) is True


def test_two_elements_rotated_true():
    # Right shift by 1 of [1,2] is [2,1]; must be True
    assert move_one_ball([2, 1]) is True


def test_rotation_needing_left_shift_one():
    # sorted=[1,2,3,4,5]; arr[1:]+arr[:1]==sorted, missed if loop starts at 2
    assert move_one_ball([5, 1, 2, 3, 4]) is True


def test_rotation_needing_various_shifts():
    assert move_one_ball([2, 3, 4, 5, 1]) is True
    assert move_one_ball([4, 5, 1, 2, 3]) is True
    assert move_one_ball([1, 5, 2, 3, 4]) is False


def test_returns_bool():
    assert type(move_one_ball([])) is bool
    assert type(move_one_ball([3, 4, 5, 1, 2])) is bool
    assert type(move_one_ball([3, 5, 4, 1, 2])) is bool


def test_does_not_mutate_input():
    arr = [3, 4, 5, 1, 2]
    snapshot = list(arr)
    move_one_ball(arr)
    assert arr == snapshot


# ---- property-based tests ----

@given(st.lists(st.integers(min_value=-50, max_value=50), min_size=0, max_size=8, unique=True))
def test_equivalence_to_reference_model(arr):
    assert move_one_ball(list(arr)) == reference(list(arr))


@given(st.lists(st.integers(min_value=-100, max_value=100), min_size=0, max_size=10, unique=True))
def test_sorted_input_always_true(arr):
    assert move_one_ball(sorted(arr)) is True


@given(st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=10, unique=True),
       st.integers(min_value=0, max_value=20))
def test_all_rotations_of_sorted_are_true(arr, k):
    s = sorted(arr)
    assert move_one_ball(right_shift(s, k)) is True


@given(st.lists(st.integers(min_value=-50, max_value=50), min_size=0, max_size=8, unique=True),
       st.integers(min_value=0, max_value=20))
def test_invariance_under_right_shift(arr, k):
    assert move_one_ball(right_shift(list(arr), k)) == move_one_ball(list(arr))


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=3, max_size=7, unique=True))
def test_swap_breaks_sorted_rotation_unless_still_rotation(arr):
    s = sorted(arr)
    n = len(s)
    # swap two distinct positions in a sorted list; result should be True
    # iff it still equals some rotation (reference check)
    for i in range(n):
        for j in range(i + 1, n):
            b = list(s)
            b[i], b[j] = b[j], b[i]
            assert move_one_ball(b) == reference(b)


@given(st.lists(st.integers(min_value=-50, max_value=50), min_size=0, max_size=8, unique=True))
def test_idempotence_of_sorted_check(arr):
    # applying sorted() to any rotation yields True; and result is stable
    r1 = move_one_ball(list(arr))
    r2 = move_one_ball(list(arr))
    assert r1 == r2
    assert r1 is True or r1 is False


@given(st.integers(min_value=-100, max_value=100))
def test_singleton_always_true(x):
    assert move_one_ball([x]) is True
